     1	import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
     2	import type {ToolRegistry} from './tools/registry.js';
     3	import type {ToolCall, UsageMetadata} from '../types/ai.js';
     4	
     5	// All three conditions matter; dropping the registry check spins the tool loop.
     6	
     7	const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
     8	const REGISTRY = {} as ToolRegistry;
     9	
    10	describe('shouldContinueToolLoop', () => {
    11	  it('continues when the model requested a tool and a registry can run it', () => {
    12	    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
    13	  });
    14	
    15	  it('stops when no registry is configured, whatever the model asked for', () => {
    16	    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
    17	  });
    18	
    19	  it('stops when the model named no tool', () => {
    20	    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
    21	  });
    22	
    23	  it('stops when the model finished for a reason other than tool use', () => {
    24	    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
    25	  });
    26	});
    27	
    28	describe('accumulateUsage', () => {
    29	  it('sums token fields when both operands are defined', () => {
    30	    const a: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    31	    const b: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    32	    expect(accumulateUsage(a, b)).toEqual({inputTokens: 35, outputTokens: 12, totalTokens: 47});
    33	  });
    34	
    35	  it('returns the defined side when one operand is undefined', () => {
    36	    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    37	    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    38	    expect(accumulateUsage(usage, undefined)).toEqual(usage);
    39	  });
    40	
    41	  it('returns undefined when both operands are undefined', () => {
    42	    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
    43	  });
    44	});
specs/hal-engine-architecture/spec.md:340:- A round continues only when the model stopped for `tool_use`, named at least one tool, and a `ToolRegistry` is configured ([validated by: continues when the model requested a tool and a registry can run it](../../src/orchestration/orchestratorHelpers.test.ts#L11)).
specs/hal-engine-architecture/spec.md:341:- With no registry configured the loop stops, whatever the model asked for, because nothing could execute the call ([validated by: stops when no registry is configured, whatever the model asked for](../../src/orchestration/orchestratorHelpers.test.ts#L15)).
specs/hal-engine-architecture/spec.md:342:- A `tool_use` stop naming no tool stops the loop, rather than re-querying with nothing to add ([validated by: stops when the model named no tool](../../src/orchestration/orchestratorHelpers.test.ts#L19)).
specs/hal-engine-architecture/spec.md:343:- Any other stop reason ends the loop even when tool calls are pending ([validated by: stops when the model finished for a reason other than tool use](../../src/orchestration/orchestratorHelpers.test.ts#L23)).
8:`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.
18:- `afterModelResponse` is called once per user message after the round loop exits and receives the `UsageMetadata` summed across every provider call in that turn, rather than only the final round's usage ([validated by: reports usage summed across every provider call when a turn runs through two tool rounds](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L53)).
19:- When some rounds in a turn omit `usage`, `afterModelResponse` receives the sum of the rounds that reported it, and when no round in the turn reported `usage`, it receives `undefined` ([validated by: counts the rounds that reported usage when some omit it, and reports undefined when none did](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L63)).

